UPDATE products
SET title = CASE WHEN product_id='prod_0001' THEN title ELSE (
      SELECT scopes.scope || '·' || products.category || CASE CAST(substr(products.product_id,-4) AS INTEGER) % 3 WHEN 1 THEN 'fixedtranslatedcandidate' WHEN 2 THEN 'clamptranslatedcandidate' ELSE 'translatedtranslatedtranslatedcandidate' END
      FROM scopes WHERE scopes.n=CAST((CAST(substr(products.product_id,-4) AS INTEGER)+2)/3 AS INTEGER)
    ) END,
    description = (
      SELECT scopes.scope || ' is used for home livestream studioof' || products.category || 'configuration；' || scopes.constraint_fact || '；' || CASE CAST(substr(products.product_id,-4) AS INTEGER) % 3 WHEN 1 THEN 'fixedtranslatedtranslatedtranslatedmustfirstverifytranslatedtranslatedauthorization。' WHEN 2 THEN 'clamptranslatedtranslatedtranslatedmustrecordtranslatedtranslatedtranslatedtranslatedtranslated。' ELSE 'translatedtranslatedtranslatedsetupmusttranslatedtranslatedtranslatedtranslatedandorganization。' END
      FROM scopes WHERE scopes.n=CAST((CAST(substr(products.product_id,-4) AS INTEGER)+2)/3 AS INTEGER)
    )
WHERE product_id GLOB 'prod_[0-9][0-9][0-9][0-9]';

