UPDATE skus
SET attrs_json = (
  SELECT json_object(
    'application', scopes.scope,
    'safety_constraint', scopes.constraint_fact,
    'form_factor', CASE CAST(substr(skus.sku_id,-4) AS INTEGER) % 3 WHEN 1 THEN 'fixed' WHEN 2 THEN 'clamp' ELSE 'portable' END,
    'finish', CASE products.category WHEN 'renovationmaterial' THEN 'low_voc_reviewed' WHEN 'cable organization' THEN 'reversible' ELSE 'equipment_grade' END
  )
  FROM scopes JOIN products ON products.product_id=skus.product_id
  WHERE scopes.n=CAST((CAST(substr(skus.sku_id,-4) AS INTEGER)+2)/3 AS INTEGER)
)
WHERE sku_id GLOB 'sku_[0-9][0-9][0-9][0-9]';
